def esc(s): return str(s).replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
def yen(n): return f'{n:,}'


# ------------------------------------------------------------------------------------------ Word
W_NS = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'


def _fld(instr, shown):
    return parse_xml(f'<w:fldSimple {W_NS} w:instr=" {instr} "><w:r><w:t>{shown}</w:t></w:r></w:fldSimple>')


def rdocx(path, title, blocks, header=None, footer='page', author='先方 法務部', date='2026-11-18T10:24:00Z', size=10.5):
    """Word 文書。blocks の要素：
       文字列（段落）／'## 見出し'／'---pb---'（改ページ）／('table', rows)／
       ('trk', [('', 文字), ('ins', 挿入した文字), ('del', 削除した文字), …])＝変更履歴が残った段落"""
    d = docx.Document()
    st = d.styles['Normal']; st.font.name = 'Yu Mincho'; st.font.size = Pt(size)
    st.element.rPr.rFonts.set(qn('w:eastAsia'), 'Noto Serif CJK JP')
    sec = d.sections[0]
    sec.page_width, sec.page_height = Mm(210), Mm(297)  # A4（python-docx の既定は Letter。国内の実務の文書に合わせる）
    if header: sec.header.paragraphs[0].text = header
    if footer == 'page':
        p = sec.footer.paragraphs[0]; p.alignment = 1
        p.add_run('- '); p._p.append(_fld('PAGE', '1')); p._p.append(parse_xml(f'<w:r {W_NS}><w:t xml:space="preserve"> / </w:t></w:r>'))
        p._p.append(_fld('NUMPAGES', '1')); p._p.append(parse_xml(f'<w:r {W_NS}><w:t xml:space="preserve"> -</w:t></w:r>'))
    elif footer: sec.footer.paragraphs[0].text = footer
    if title: d.add_heading(title, 1)
    cid = 100
    for b in blocks:
        if isinstance(b, str):
            if b.startswith('## '): d.add_heading(b[3:], 2)
            elif b == '---pb---': d.add_page_break()
            else: d.add_paragraph(b)
        elif b[0] == 'table':
            rows = b[1]; t = d.add_table(rows=len(rows), cols=max(len(r) for r in rows)); t.style = 'Table Grid'
            for i, r in enumerate(rows):
                for j, v in enumerate(r): t.cell(i, j).text = str(v)
            d.add_paragraph('')
        elif b[0] == 'trk':
            p = d.add_paragraph()
            for kind, t in b[1]:
                if kind == '': p._p.append(parse_xml(f'<w:r {W_NS}><w:t xml:space="preserve">{esc(t)}</w:t></w:r>'))
                else:
                    cid += 1; tag, tt = ('w:ins', 'w:t') if kind == 'ins' else ('w:del', 'w:delText')
                    p._p.append(parse_xml(f'<{tag} {W_NS} w:id="{cid}" w:author="{author}" w:date="{date}"><w:r><{tt} xml:space="preserve">{esc(t)}</{tt}></w:r></{tag}>'))
    d.save(P(path))


def trk_final(blocks):
    """変更履歴をすべて承諾したあとの本文（正解の確認や、PDF にする版に使う）"""
    out = []
    for b in blocks:
        if isinstance(b, tuple) and b[0] == 'trk': out.append(''.join(t for k, t in b[1] if k != 'del'))
        else: out.append(b)
    return out


