# ------------------------------------------------------------------------------------------ Excel
def share_formulas(path, sheet, col, r1, r2, si=0):
    """Excel で数式を下へコピーしたときと同じ「共有数式」の形に書き直す（先頭のセルだけが式を持つ）"""
    p = P(path); zin = zipfile.ZipFile(p); items = [(i, zin.read(i.filename)) for i in zin.infolist()]; zin.close()
    name = f'xl/worksheets/sheet{sheet}.xml'
    with zipfile.ZipFile(p, 'w', zipfile.ZIP_DEFLATED) as z:
        for i, b in items:
            if i.filename == name:
                s = b.decode('utf-8')
                for r in range(r1, r2 + 1):
                    m = re.search(rf'(<c r="{col}{r}"[^>]*>)<f>([^<]*)</f>', s)
                    assert m, (path, col, r)
                    f = f'<f t="shared" ref="{col}{r1}:{col}{r2}" si="{si}">{m.group(2)}</f>' if r == r1 else f'<f t="shared" si="{si}"/>'
                    s = s[:m.start()] + m.group(1) + f + s[m.end():]
                b = s.encode('utf-8')
            z.writestr(i.filename, b)


# ------------------------------------------------------------------------------------------ PDF
def hb(blocks):
    """段落の並びを HTML にする。'# '・'## ' は見出し、('table', rows[, 'nohead']) は表、('raw', html) はそのまま"""
    o = []
    for x in blocks:
        if isinstance(x, tuple) and x[0] == 'table':
            head = not (len(x) > 2 and x[2] == 'nohead')
            o.append('<table>' + ''.join('<tr>' + ''.join((f'<th>{esc(c)}</th>' if i == 0 and head else f'<td>{esc(c)}</td>') for c in r) + '</tr>' for i, r in enumerate(x[1])) + '</table>')
        elif isinstance(x, tuple) and x[0] == 'raw': o.append(x[1])
        elif x == '---pb---': o.append('<div class="pb"></div>')
        elif x.startswith('# '): o.append(f'<h1>{esc(x[2:])}</h1>')
        elif x.startswith('## '): o.append(f'<h2>{esc(x[3:])}</h2>')
        else: o.append(f'<p>{esc(x)}</p>')
    return ''.join(o)


def page(body, css='', serif=True, size='10.5pt'):
    fam = "'Noto Serif CJK JP'" if serif else "'Noto Sans CJK JP'"
    return f"""<html><head><meta charset="utf-8"><style>body{{font-family:{fam};font-size:{size};line-height:1.75;margin:0}}
h1{{font-size:17pt;text-align:center;margin:0 0 14px}}h2{{font-size:12pt;margin:16px 0 4px}}p{{margin:0 0 4px;text-align:justify}}
table{{border-collapse:collapse;width:100%;margin:6px 0 10px}}td,th{{border:1px solid #333;padding:3px 7px;font-size:9.5pt;vertical-align:top}}th{{background:#e8e8e8}}
.pb{{page-break-before:always}}.r{{text-align:right}}.c{{text-align:center}}{css}</style></head><body>{body}</body></html>"""


def cpdf(path, html, **opts): PDFQ.append((P(path), html, opts))


def hf(left='', right=''):
    """ブラウザの印刷のヘッダー・フッター（左の文字、右の文字。右の {p}/{n} はページ番号）"""
    r = right.replace('{p}', '<span class="pageNumber"></span>').replace('{n}', '<span class="totalPages"></span>')
    return f'<div style="font-size:8px;width:100%;padding:0 14mm;display:flex;justify-content:space-between;font-family:\'Noto Sans CJK JP\'"><span>{left}</span><span>{r}</span></div>'


def rasterize(pdf, dpi=150):
    tmp = tempfile.mkdtemp()
    subprocess.run(['pdftoppm', '-r', str(dpi), '-png', pdf, os.path.join(tmp, 'p')], check=True)
    ims = [Image.open(os.path.join(tmp, f)).convert('RGB') for f in sorted(os.listdir(tmp))]
    shutil.rmtree(tmp); return ims


def stamp(im, x, y, label, color=(200, 30, 30), r=62):
    d = ImageDraw.Draw(im); d.ellipse([x - r, y - r, x + r, y + r], outline=color, width=5)
    f = font(int(r * 0.62), True); w = d.textlength(label, font=f); d.text((x - w / 2, y - r * 0.42), label, fill=color, font=f)


def red_note(im, x, y, s, size=34, circle=None):
    """朱書き（赤ペンの書き込み）。circle=(x1, y1, x2, y2) で囲みも描く"""
    d = ImageDraw.Draw(im)
    if circle: d.ellipse(circle, outline=(215, 35, 35), width=5); d.line([circle[2] - 10, circle[1] + 10, x, y + size / 2], fill=(215, 35, 35), width=4)
    d.text((x, y), s, fill=(215, 35, 35), font=font(size, True))


def scan_look(im, rot=0.0, offset=(0, 0), noise=3000, gray=False, dark=1.0, blur=0.7):
    """紙を取り込んだスキャン風にする（ずれ・傾き・ぼけ・ごみ・濃さ）"""
    W, H = im.size
    if offset != (0, 0):
        bg = Image.new('RGB', (W, H), 'white'); bg.paste(im, offset); im = bg
    if rot: im = im.rotate(rot, resample=Image.BICUBIC, fillcolor='white')
    im = im.filter(ImageFilter.GaussianBlur(blur))
    if gray: im = im.convert('L').convert('RGB')
    if dark != 1.0: im = Image.eval(im, lambda v: max(0, min(255, int(255 - (255 - v) * dark))))
    px = im.load()
    for _ in range(noise):
        x, y = random.randrange(W), random.randrange(H); v = random.randint(150, 220); px[x, y] = (v, v, v)
    return im


def save_scan(path, ims, dpi=150): ims[0].save(P(path), save_all=True, append_images=ims[1:], resolution=dpi)


def encrypt_pdf(src, dst, pw):
    from pypdf import PdfReader, PdfWriter
    r = PdfReader(src); w = PdfWriter()
    for pg in r.pages: w.add_page(pg)
    w.encrypt(pw, algorithm='AES-256'); w.write(dst)


def wbytes(path, b):
    with open(P(path), 'wb') as f: f.write(b)


