    after.insert(k + 1, ['6235', '貸倒引当金繰入額', 0, 1_184_000, 0]); adj('貸倒引当金', cr=1_184_000)

    def make(path, data, title, bug=False):
        wb = xlsxwriter.Workbook(P(path))
        f_h = wb.add_format({'bold': True, 'bg_color': '#DDEBF7', 'border': 1, 'align': 'center'})
        f_n = wb.add_format({'num_format': '#,##0;"△"#,##0', 'border': 1}); f_t = wb.add_format({'border': 1}); f_b = wb.add_format({'bold': True, 'num_format': '#,##0;"△"#,##0', 'border': 1, 'top': 6})
        f_p = wb.add_format({'num_format': '0.0%;"△"0.0%', 'border': 1}); f_title = wb.add_format({'bold': True, 'size': 14}); f_d = wb.add_format({'num_format': 'yyyy"年"m"月"d"日"'})
        ws = wb.add_worksheet('試算表'); ws.set_column(0, 0, 8); ws.set_column(1, 1, 26); ws.set_column(2, 5, 16)
        ws.write(0, 0, title, f_title); ws.write(1, 0, '株式会社ノースリーフ　第12期（2025年12月1日〜2026年11月30日）'); ws.write(1, 4, '作成日'); ws.write_datetime(1, 5, datetime.datetime(2026, 12, 8 if '後' in title else 3), f_d)
        for j, h in enumerate(['コード', '勘定科目', '前月残高', '当月借方', '当月貸方', '当月残高']): ws.write(2, j, h, f_h)
        for i, (code, name, base, dr, cr) in enumerate(data):
            r = 3 + i; ws.write(r, 0, code, f_t); ws.write(r, 1, name, f_t); ws.write_number(r, 2, base, f_n); ws.write_number(r, 3, dr, f_n); ws.write_number(r, 4, cr, f_n)
            ws.write_formula(r, 5, f'=C{r + 1}+D{r + 1}-E{r + 1}', f_n, base + dr - cr)
        n = len(data); last = 3 + n   # 合計の行（0始まり）
        ws.write(last, 1, '合計', f_b)
        for j, col in enumerate('CDEF'):
            end = last - 1 if (bug and col in 'DE') else last   # 行を足したのに、合計の範囲を広げ忘れた（借方・貸方）
            tot = sum((x[2], x[3], x[4], x[2] + x[3] - x[4])[j] for x in (data[:-1] if end != last else data))
            ws.write_formula(last, 2 + j, f'=SUM({col}4:{col}{end})', f_b, tot)
        ws.write(last + 1, 1, '貸借差額（借方−貸方）'); ws.write_formula(last + 1, 3, f'=D{last + 1}-E{last + 1}', f_n, sum(x[3] for x in data) - sum(x[4] for x in data))
