def r04(d):
    m = {'top': '20mm', 'bottom': '20mm', 'left': '20mm', 'right': '20mm'}
    for ver, name, hd, dt in [(0, '傷害保険普通保険約款_2025年4月版.pdf', '傷害保険普通保険約款（2025年4月版）', '印刷 2025/02/14'), (1, '傷害保険普通保険約款_2027年4月改定版.pdf', '傷害保険普通保険約款（2027年4月改定版）', '印刷 2026/11/20')]:
        cpdf(f'{d}/{name}', page(hb(yakkan(ver)), size='12pt'), margin=m, display_header_footer=True, header_template=hf(hd, 'あおば損害保険株式会社'), footer_template=hf(dt, '{p} / {n}'))
    wb = xlsxwriter.Workbook(P(f'{d}/改定箇所一覧_商品開発部作成.xlsx')); ws = wb.add_worksheet('改定箇所'); h = wb.add_format({'bold': True, 'bg_color': '#FFF2CC', 'border': 1}); c = wb.add_format({'border': 1, 'text_wrap': True, 'valign': 'top'})
