def r05(d):
    rnd = random.Random(505)
    items = [('外径 φA', 25.000, 0.021, 'mm'), ('外径 φB', 18.000, 0.018, 'mm'), ('内径 φC', 12.000, 0.018, 'mm'), ('全長 L1', 86.50, 0.10, 'mm'), ('段差 L2', 22.30, 0.05, 'mm'), ('溝幅 W', 3.20, 0.05, 'mm'), ('溝深さ D', 1.50, 0.05, 'mm'), ('面取り C1', 0.50, 0.10, 'mm'),
             ('同軸度', 0.000, 0.020, 'mm'), ('真円度', 0.000, 0.008, 'mm'), ('表面粗さ Ra', 0.00, 1.60, 'μm'), ('ねじ M8×1.25', None, None, 'ゲージ')]
    def page_rows(seed, shift=0.0, ng=None):
        r = random.Random(seed); rows = [['No', '検査項目', '規格', 'n1', 'n2', 'n3', 'n4', 'n5', '判定']]
        for i, (nm, nom, tol, unit) in enumerate(items):
            if nom is None: rows.append([i + 1, nm, '通り／止まり', '合', '合', '合', '合', '合', '合格']); continue
            dec = 3 if tol < 0.03 else 2
            if nom == 0: vals = [abs(r.gauss(tol * 0.35, tol * 0.15)) for _ in range(5)]; spec = f'{tol:.{dec}f} 以下'
            else: vals = [nom + r.gauss(shift, tol * 0.3) for _ in range(5)]; spec = f'{nom:.{dec}f} ±{tol:.{dec}f}'
            if ng == i: vals[2] = nom + tol * 1.35
            ok = all((x <= tol) if nom == 0 else abs(x - nom) <= tol for x in vals)
            rows.append([i + 1, nm, spec + ' ' + unit] + [f'{x:.{dec}f}' for x in vals] + ['合格' if ok else '不合格'])
        return rows
    def sheet(pg, total, title, rows, extra='', date='2026年11月12日', insp='検査員　大橋'):
        return hb([f'# 検査成績書（{title}）', ('table', [['品名', 'シャフト（出力軸）', '図番', 'SH-4471-C'], ['ロット番号', 'A2611', '数量', '480個'], ['材質', 'SCM435', '熱処理', '焼入焼戻し HRC 28〜34'], ['検査日', date, '検査', insp]], 'nohead'),
                   ('table', rows)] + ([extra] if extra else []) + [('raw', f'<p class="r" style="margin-top:14px">東和精工株式会社　品質保証部　　　　ページ {pg} / {total}</p>')])
    def build(resub):
        total = 11 if resub else 10; pages = []
        for k in range(10):
            pg = len(pages) + 1
            if k == 3 and not resub: pages.append(sheet(pg, total, f'寸法検査　サンプル群 {k + 1}', page_rows(100 + k, ng=1), '備考：No.2 外径 φB の n3 が規格外。再測定のうえ報告する。'))
            elif k == 3: pages.append(sheet(pg, total, f'寸法検査　サンプル群 {k + 1}（再測定）', page_rows(900 + k), '備考：三次元測定機の校正後に再測定（2026年11月19日）。全数合格。', date='2026年11月19日', insp='検査員　大橋・立会 村井'))
            else: pages.append(sheet(pg, total, f'寸法検査　サンプル群 {k + 1}', page_rows(100 + k)))
            if k == 6 and resub:
                hr = [['No', '測定位置', '規格', 'n1', 'n2', 'n3', '判定']] + [[i + 1, p, 'HRC 28〜34'] + [f'{random.Random(70 + i * 3 + j).uniform(29.5, 32.8):.1f}' for j in range(3)] + ['合格'] for i, p in enumerate(['軸端 A 側', '中央部', '軸端 B 側', '溝底部', 'ねじ部'])]
                pages.append(hb(['# 検査成績書（追加検査　硬さ試験）', ('table', [['品名', 'シャフト（出力軸）', '図番', 'SH-4471-C'], ['ロット番号', 'A2611', '試験機', 'ロックウェル硬さ試験機 HR-430'], ['検査日', '2026年11月19日', '検査', '検査員　村井']], 'nohead'), ('table', hr), '備考：客先要求により追加実施。',
                                 ('raw', f'<p class="r" style="margin-top:14px">東和精工株式会社　品質保証部　　　　ページ {len(pages) + 1} / {total}</p>')]))
        return '<div class="pb"></div>'.join(pages)
    m = {'top': '16mm', 'bottom': '16mm', 'left': '14mm', 'right': '14mm'}
    cpdf(f'{d}/_tmp_初回.pdf', page(build(False), serif=False), margin=m); cpdf(f'{d}/_tmp_再提出.pdf', page(build(True), serif=False), margin=m)
    def post():
        r = random.Random(55)
        for src, dst, st in [('_tmp_初回.pdf', '検査成績書_ロットA2611_初回提出スキャン.pdf', '検査'), ('_tmp_再提出.pdf', '検査成績書_ロットA2611_再提出スキャン.pdf', '再検')]:
            ims = rasterize(P(f'{d}/{src}')); out = []
            for i, im in enumerate(ims):
                stamp(im, 1090, 150, st); stamp(im, 950, 150, '承認' if dst.startswith('検査成績書_ロットA2611_再') else '大橋', color=(190, 40, 40), r=52)
                out.append(scan_look(im, rot=r.uniform(-0.6, 0.6), offset=(r.randint(-10, 10), r.randint(-10, 10)), gray=True, dark=r.uniform(0.95, 1.12)))
            save_scan(f'{d}/{dst}', out); os.remove(P(f'{d}/{src}'))
    POST.append(post)
    steps = [['工程', '作業内容', '管理項目・規格', '使用設備・治工具', '確認頻度'], ['1 受入', '素材の材質証明書とロット番号を照合する', 'SCM435、ミルシート添付', '―', '全ロット'], ['2 荒加工', '外径・端面を荒加工する', '外径 φ25.5 ±0.1', 'NC旋盤 L-03', '初品・1回/50個'],
             ['3 熱処理', '焼入焼戻しを行う', 'HRC 28〜34', '連続炉 HT-2', '1回/ロット'], ['4 仕上加工', '外径・溝を仕上加工する', '外径 φ25.000 ±0.021', 'NC旋盤 L-07', '初品・1回/20個'], ['5 ねじ加工', 'M8×1.25 のねじを加工する', 'ゲージ通り・止まり', 'タッピングセンタ T-01', '初品・1回/20個'],
             ['6 締付', '治具にセットしボルトを締め付ける', '締付トルク 12 N·m', 'トルクレンチ TW-12', '全数'], ['7 洗浄', '切粉・油分を除去する', '残渣なきこと（目視）', '洗浄機 W-01', '全数'], ['8 検査', '寸法・外観を検査する', '検査基準書 QI-4471 による', '三次元測定機、マイクロメータ', '抜取 n=5/ロット'], ['9 梱包', '防錆紙で包み通い箱に入れる', '1箱 40個', '―', '全数']]
    intro = ['## 1 目的', 'この標準書は、シャフト（出力軸）SH-4471-C の加工及び検査の作業方法を定め、品質の安定を図ることを目的とする。', '## 2 適用範囲', '第2工場 機械加工課の SH-4471 系列の加工に適用する。', '## 3 作業手順']
