# R06 プラント設計：P&ID（ベクターPDF A3 2シート、Rev2→Rev3）・朱書きスキャン・機器リスト
# ==========================================================================================
def pid(path, rev):
    v = rev >= 3; c = rl_canvas.Canvas(P(path), pagesize=landscape(A3)); W, H = landscape(A3)
    def T(x, y, s, sz=8): c.setFont('IPAG', sz); c.drawString(x, y, s)
    def frame(sheet, title):
        c.setLineWidth(1.5); c.rect(20, 20, W - 40, H - 40); c.setLineWidth(0.8); c.rect(W - 330, 20, 310, 90)
        for k in (1, 2, 3): c.line(W - 330, 20 + k * 22.5, W - 20, 20 + k * 22.5)
        T(W - 322, 94, f'図番 PID-2201-{sheet:02d}　　Rev.{rev}', 10); T(W - 322, 71, f'名称 {title}', 9); T(W - 322, 49, '北浜ケミカル株式会社 第2プラント　純水・薬液供給設備', 8)
        T(W - 322, 27, f'設計 相馬　検図 西田　承認 {"林 2026/11/21" if v else "林 2026/06/30"}　尺度 NTS　{sheet}/2', 8)
        c.rect(W - 330, 110, 310, 14 * (4 if v else 3)); T(W - 322, 114, 'Rev  日付        改訂内容', 7)
        revs = [('1', '2026/03/02', '新規発行'), ('2', '2026/06/30', '客先コメント反映')] + ([('3', '2026/11/21', 'PW 配管 口径変更、V-207 追加、LT-102 追加')] if v else [])
        for i, (a, b, s) in enumerate(revs): T(W - 322, 128 + i * 14, f'{a}    {b}  {s}', 7)
    def tank(x, y, w, h, tag, name, spec):
        c.setLineWidth(1.2); c.rect(x, y, w, h); c.ellipse(x, y + h - 8, x + w, y + h + 8); T(x + 6, y + h / 2 + 4, tag, 10); T(x + 6, y + h / 2 - 10, name, 8); T(x + 6, y - 12, spec, 7)
    def pump(x, y, tag):
        c.setLineWidth(1.2); c.circle(x, y, 14); c.line(x - 14, y - 14, x + 14, y - 14); c.line(x, y, x + 12, y + 7); T(x - 16, y - 28, tag, 8)
    def valve(x, y, tag, vert=False):
        c.setLineWidth(1); p = c.beginPath()
        if vert: p.moveTo(x - 6, y - 9); p.lineTo(x + 6, y - 9); p.lineTo(x - 6, y + 9); p.lineTo(x + 6, y + 9); p.close()
        else: p.moveTo(x - 9, y - 6); p.lineTo(x - 9, y + 6); p.lineTo(x + 9, y - 6); p.lineTo(x + 9, y + 6); p.close()
        c.drawPath(p); T(x - 12, y + 11, tag, 7)
    def inst(x, y, a, b):
        c.setLineWidth(0.8); c.circle(x, y, 13); c.line(x - 13, y, x + 13, y); T(x - 8, y + 2, a, 7); T(x - 8, y - 9, b, 7)
    def line(pts, label=None, lx=0, ly=0, dash=False):
        c.setLineWidth(1.4); c.setDash(4, 3) if dash else c.setDash()
        for (x1, y1), (x2, y2) in zip(pts, pts[1:]): c.line(x1, y1, x2, y2)
        c.setDash()
        (x1, y1), (x2, y2) = pts[-2], pts[-1]; p = c.beginPath()
        if x2 != x1: s = 1 if x2 > x1 else -1; p.moveTo(x2, y2); p.lineTo(x2 - 8 * s, y2 + 3); p.lineTo(x2 - 8 * s, y2 - 3)
        else: s = 1 if y2 > y1 else -1; p.moveTo(x2, y2); p.lineTo(x2 + 3, y2 - 8 * s); p.lineTo(x2 - 3, y2 - 8 * s)
        p.close(); c.drawPath(p, fill=1)
        if label: T(lx, ly, label, 7)
    def cloud(x, y, w, h, n):
        c.setLineWidth(0.7); c.setDash(2, 2); c.roundRect(x, y, w, h, 10); c.setDash(); p = c.beginPath(); p.moveTo(x + w + 4, y + h + 2); p.lineTo(x + w + 18, y + h + 2); p.lineTo(x + w + 11, y + h + 14); p.close(); c.drawPath(p); T(x + w + 8, y + h + 4, str(n), 7)
    # ---- シート1：純水供給
    frame(1, '配管計装線図（純水供給系統）'); pw = '80A' if v else '50A'
    tank(90, 420, 130, 220, 'TK-101', '純水タンク', '容量 20 m3　SUS304　大気圧／常温'); tank(760, 440, 110, 180, 'TK-102', '純水サービスタンク', '容量 5 m3　SUS304')
    pump(330, 400, 'P-101A'); pump(330, 310, 'P-101B'); T(360, 396, '20 m3/h × 35 m　7.5 kW' if not v else '30 m3/h × 35 m　11 kW', 7); T(360, 306, '（予備機）', 7)
    line([(220, 440), (270, 440), (270, 400), (316, 400)], f'{pw}-PW-1001-SUS304', 226, 446); line([(270, 400), (270, 310), (316, 310)])
    line([(344, 400), (520, 400), (520, 520), (760, 520)], f'{pw}-PW-1002-SUS304', 530, 526); line([(344, 310), (420, 310), (420, 400)])
    valve(292, 400, 'V-201'); valve(292, 310, 'V-202'); valve(390, 400, 'V-203'); valve(390, 310, 'V-204'); valve(640, 520, 'FCV-101')
    inst(600, 570, 'FIC', '101'); line([(600, 557), (600, 520)], dash=True); inst(155, 690, 'LIC', '101'); line([(155, 677), (155, 648)], dash=True); inst(460, 450, 'PI', '101'); line([(460, 437), (460, 400)], dash=True)
    line([(870, 500), (1000, 500)], '40A-PW-1003-SUS304　→ 薬液調合系統（シート2）', 880, 506); valve(940, 500, 'V-205')
    line([(815, 440), (815, 380), (1000, 380)], '25A-DR-1004-PVC　→ 排水ピット', 825, 386); valve(815, 410, 'V-206', vert=True)
