    def tate(paras, cols=21, rows=40):
        pages = [[]]; used = 4
        for p in paras:
            need = -(-len(plain(p)) // rows)
            if used + need > cols: pages.append([]); used = 0
            pages[-1].append(p); used += need
        html = ''
        for i, pg in enumerate(pages):
            body = ('<h1>活字の重さ</h1><p class="au">連載　まちの仕事場　第12回</p>' if i == 0 else '') + ''.join('<p>' + re.sub(r'｜(.+?)《(.+?)》', r'<ruby>\1<rt>\2</rt></ruby>', esc(x)) + '</p>' for x in pg)
            html += f'<div class="tp{" pb" if i else ""}"><div class="tx">{body}</div><div class="no">月刊まちかど 2027年1月号　{48 + i}</div></div>'
        return page(html, css='.tp{position:relative;width:170mm;height:250mm}.tx{writing-mode:vertical-rl;width:170mm;height:238mm;font-size:11pt;line-height:1.95;overflow:hidden}.tx p{margin:0;text-align:justify}.tx h1{font-size:18pt;margin:0 0 0 18px;text-align:start}.au{margin:0 0 0 22px!important;text-indent:6em}.no{position:absolute;bottom:0;left:0;right:0;text-align:center;font-size:8.5pt;font-family:"Noto Sans CJK JP"}')
