        tbl = [['Sample', 'Cu (wt%)', 'Cu²⁺ fraction', 'TOF (10⁻³ s⁻¹)'], ['Cu-0.8', '0.8', '0.86', '4.2' if not v else '4.4'], ['Cu-1.6', '1.6', '0.74', '3.7'], ['Cu-2.4', '2.4', '0.63', '3.1'], ['Cu-3.2', '3.2', '0.52', '2.5'], ['Cu-4.1', '4.1', '0.41', '1.9']]
        refs = ['Busca, G. et al. Appl. Catal. B 18, 1–36 (1998).', 'Skalska, K. et al. Sci. Total Environ. 408, 3976–3989 (2010).', 'Forzatti, P. Appl. Catal. A 222, 221–236 (2001).', 'Brandenberger, S. et al. Catal. Rev. 50, 492–531 (2008).', 'Beale, A. M. et al. Chem. Soc. Rev. 44, 7371–7405 (2015).', 'Han, L. et al. Chem. Rev. 119, 10916–10976 (2019).', 'Kwak, J. H. et al. J. Catal. 275, 187–190 (2010).', 'Fickel, D. W. et al. Appl. Catal. B 102, 441–448 (2011).', 'Paolucci, C. et al. J. Am. Chem. Soc. 138, 6028–6048 (2016).', 'Borfecchia, E. et al. Chem. Sci. 6, 548–563 (2015).', 'Gao, F. et al. J. Catal. 319, 1–14 (2014).']
