def main(only=None):
    if os.path.exists(ROOT):
        for n in os.listdir(ROOT):
            if n.startswith('R') and os.path.isdir(os.path.join(ROOT, n)) and (not only or int(n[1:3]) in only): shutil.rmtree(os.path.join(ROOT, n))
    for no, role, dept, gen in SPEC:
        if only and no not in only: continue
        gen(f'R{no:02d}_{dept}_{role}'); print('gen', no, role, flush=True)
    async def mk():
        from playwright.async_api import async_playwright
        async with async_playwright() as p:
            b = await p.chromium.launch(executable_path=G.chrome_path(), args=['--no-sandbox']); pg = await b.new_page()
            for path, html, o in PDFQ:
                await pg.set_content(html); await pg.wait_for_timeout(150)
                await pg.pdf(path=path, format=o.get('format', 'A4'), landscape=o.get('landscape', False), margin=o.get('margin'), print_background=True, display_header_footer=o.get('display_header_footer', False), header_template=o.get('header_template', '<span></span>'), footer_template=o.get('footer_template', '<span></span>'))
            await b.close()
    if PDFQ: asyncio.run(mk())
    for src, dst, fmt in SOQ:
        tmp = tempfile.mkdtemp()
        subprocess.run(['soffice', '--headless', '--convert-to', fmt, '--outdir', tmp, src], check=True, capture_output=True, timeout=180)
        shutil.move(os.path.join(tmp, os.path.splitext(os.path.basename(src))[0] + '.' + fmt), dst); shutil.rmtree(tmp)
    for f in POST: f()
    for d, lines in KEYS.items():
        open(P(f'{d}/正解.md'), 'w', encoding='utf-8').write('# 用意した変更点（レビュアーは、自分で確かめたあとに照らし合わせる）\n\n' + ''.join(f'- {x}\n' for x in lines))
    print('ok', len(KEYS), ROOT)


if __name__ == '__main__':
    main(set(int(x) for x in sys.argv[1:]) or None)
